/* Turns window.REF (generated by build/ref_build.py from the cheat sheets) into library-shaped sections:
   window.REFSECTIONS = [{id:'r_<id>', title, blurb, part, groups:[{t, items:[…]}]}]
   Also folds the "Which identity do I use?" rows into TRIG's "Which method?" section. */
(() => {
  'use strict';
  const T = window.TRIG, REF = window.REF || [];
  const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

  /* exact-value table (same numbers as the game's unit-circle chapter) */
  const H = '\\tfrac12', SQ2 = '\\tfrac{\\sqrt2}{2}', SQ3 = '\\tfrac{\\sqrt3}{2}', T3 = '\\tfrac{\\sqrt3}{3}', S3 = '\\sqrt3';
  const SPECIAL = [
    [0, '0', '0', '1', '0'], [30, '\\tfrac\\pi6', H, SQ3, T3], [45, '\\tfrac\\pi4', SQ2, SQ2, '1'], [60, '\\tfrac\\pi3', SQ3, H, S3],
    [90, '\\tfrac\\pi2', '1', '0', 'U'], [120, '\\tfrac{2\\pi}3', SQ3, '-' + H, '-' + S3], [135, '\\tfrac{3\\pi}4', SQ2, '-' + SQ2, '-1'],
    [150, '\\tfrac{5\\pi}6', H, '-' + SQ3, '-' + T3], [180, '\\pi', '0', '-1', '0'], [210, '\\tfrac{7\\pi}6', '-' + H, '-' + SQ3, T3],
    [225, '\\tfrac{5\\pi}4', '-' + SQ2, '-' + SQ2, '1'], [240, '\\tfrac{4\\pi}3', '-' + SQ3, '-' + H, S3], [270, '\\tfrac{3\\pi}2', '-1', '0', 'U'],
    [300, '\\tfrac{5\\pi}3', '-' + SQ3, H, '-' + S3], [315, '\\tfrac{7\\pi}4', '-' + SQ2, SQ2, '-1'], [330, '\\tfrac{11\\pi}6', '-' + H, SQ3, '-' + T3],
    [360, '2\\pi', '0', '1', '0']
  ];
  const RC = { '0': 'U', 'U': '0', '1': '1', [H]: '2', [SQ2]: '\\sqrt2', [SQ3]: '\\tfrac{2\\sqrt3}{3}', [S3]: T3, [T3]: S3 };
  const recip = v => { const neg = v[0] === '-', m = neg ? v.slice(1) : v, o = RC[m]; return o === 'U' ? 'U' : o === '0' ? '0' : (neg ? '-' : '') + o; };
  const cell = v => `<td>\\(${v === 'U' ? '\\text{undef.}' : v}\\)</td>`;
  function valuesTable() {
    const head = ['θ°', 'θ', '\\sin', '\\cos', '\\tan', '\\csc', '\\sec', '\\cot'].map((h, i) => i < 2 ? `<th>${h}</th>` : `<th>\\(${h}\\)</th>`).join('');
    const rows = SPECIAL.map(([d, rad, s, c, t]) =>
      `<tr${d % 90 === 0 ? ' class="ax"' : ''}><td>${d}°</td><td>\\(${rad}\\)</td>${[s, c, t, recip(s), recip(c), recip(t)].map(cell).join('')}</tr>`).join('');
    return `<div class="vtwrap"><table class="vt"><tr>${head}</tr>${rows}</table></div>`;
  }

  const rich = s => esc(s);   // notes may contain $…$ (MathJax inline); everything else is plain text
  const secs = [];
  let stratGroups = null;
  REF.forEach(part => part.sections.forEach(sec => {
    const groups = [];
    sec.groups.forEach(g => {
      if (g.kind === 'circle') return;
      if (g.kind === 'table') { groups.push({ t: g.t, items: [{ k: 'txt', html: valuesTable() }], cols: 1 }); return; }
      if (g.kind === 'strat') {
        stratGroups = [{ t: 'More patterns (integrals, limits, series, area, ODEs)', items: g.f.map(([l, r]) => ({ k: 'txt', html: `<b>${rich(l)}</b><p>${rich(r)}</p>` })) }];
        return;
      }
      let cur = { t: g.t, items: [] }; groups.push(cur);
      g.f.forEach(([tex, note, v]) => {
        if (tex === '#') { cur = { t: g.t + ' · ' + note, items: [] }; groups.push(cur); return; }
        if (tex === '') { cur.items.push({ k: 'txt', html: `<p>${rich(note)}</p>` }); return; }
        const it = { k: 'id', tex };
        if (note) it.t = rich(note);
        if (v) it.chk = 1;
        cur.items.push(it);
      });
    });
    const clean = groups.filter(g => g.items.length);
    if (clean.length) secs.push({ id: 'r_' + sec.id, title: sec.title, blurb: part.sub, part: part.id, partTitle: part.title, ref: true, groups: clean });
  }));
  window.REFSECTIONS = secs;
  if (stratGroups && T) {
    const st = T.sections.find(s => s.id === 'strategy');
    if (st) st.groups = st.groups.concat(stratGroups);
  }
})();
